/*
 * This source file was generated by the Gradle 'init' task
 * Extended to include TINC Blockchain Dashboard functionality
 */
package org.example.app;

import org.example.list.LinkedList;

import static org.example.utilities.StringUtils.join;
import static org.example.utilities.StringUtils.split;
import static org.example.app.MessageUtils.getMessage;

import org.apache.commons.text.WordUtils;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Scene;
import javafx.scene.layout.BorderPane;
import javafx.stage.Stage;

import java.util.logging.Logger;
import java.util.logging.Level;

/**
 * Main Application class for TINC Blockchain
 * Combines original Gradle init functionality with JavaFX Dashboard
 */
public class App extends Application {
    private static final Logger LOGGER = Logger.getLogger(App.class.getName());

    /**
     * JavaFX Application start method - launches the dashboard
     */
    @Override
    public void start(Stage primaryStage) {
        try {
            LOGGER.info("Starting TINC Blockchain Dashboard...");

            // Load the FXML file from resources root
            FXMLLoader loader = new FXMLLoader();
            loader.setLocation(getClass().getResource("/dashboard.fxml"));

            BorderPane root = loader.load();

            // Create scene
            Scene scene = new Scene(root, 1400, 900);

            // Configure stage
            primaryStage.setTitle("TINC Blockchain Management Interface");
            primaryStage.setScene(scene);
            primaryStage.setMinWidth(1200);
            primaryStage.setMinHeight(800);

            // Show the stage
            primaryStage.show();

            LOGGER.info("TINC Blockchain Dashboard started successfully");

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Failed to start TINC Dashboard", e);
            e.printStackTrace();

            // Show error and exit
            System.err.println("Error starting dashboard: " + e.getMessage());
            System.exit(1);
        }
    }

    @Override
    public void stop() throws Exception {
        LOGGER.info("Stopping TINC Blockchain Dashboard...");
        super.stop();
    }

    /**
     * Original Gradle init functionality
     */
    private static void runOriginalApp() {
        LinkedList tokens;
        tokens = split(getMessage());
        String result = join(tokens);
        System.out.println(WordUtils.capitalize(result));
    }

    /**
     * Main entry point - launches JavaFX dashboard
     * Add --console argument to run original functionality
     */
    public static void main(String[] args) {
        // Check if running in console mode
        if (args.length > 0 && "--console".equals(args[0])) {
            System.out.println("Running TINC Blockchain in console mode...");
            runOriginalApp();
        } else {
            // Launch JavaFX dashboard
            LOGGER.info("Launching TINC Blockchain Dashboard...");
            launch(args);
        }
    }
}